{
  "anomaly_detected": true,
  "confidence": 0.99,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["J1", "Module1", "U11"],
      "pins": ["J1.15", "Module1.200", "U11.6"],
      "nets": ["/CAN0_N"],
      "observed": "The /CAN0_N net connects the CAN transceiver CANL pin U11.6 and CAN connectors to J1.15 (HDMI SCL) and Module1.200 (HDMI0_SCL).",
      "expected": "CAN0_N should be isolated from the HDMI SCL signal; the HDMI connector SCL pin and CM4 HDMI0_SCL pin should connect only to each other.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "/CAN0_N : D10.1(Input,input) J1.15(SCL,passive) J13.8(Pin_8,passive) J2.8(Pin_8,passive) Module1.200(HDMI0_SCL,open_collector) R34.1(1,passive) U11.6(CANL,bidirectional)"
        },
        {
          "source": "spec",
          "quote": "Compute carrier: hosts the CM4 (Module1), breaking out GPIO, Ethernet, USB, camera connectors, and an RTC"
        }
      ],
      "impact": "The HDMI SCL line is electrically tied to the CAN0 negative bus line, so CAN signaling can interfere with HDMI control communication and the HDMI SCL connection can load or disturb CAN0.",
      "confidence": 0.99
    }
  ],
  "summary": "An unintended bridge joins the HDMI SCL signal to CAN0_N. This couples two unrelated interfaces and is supported directly by the netlist connectivity."
}

